import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = 512;

  const aspect = rect.w / rect.h;
  const height = 1.6;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const uvScale = vec2(rect.w / atlasSize, rect.h / atlasSize);
  const uvOffset = vec2(rect.x / atlasSize, 1.0 - (rect.y + rect.h) / atlasSize);

  const material = new THREE.MeshBasicNodeMaterial();
  const mappedUv = uv().mul(uvScale).add(uvOffset);
  material.colorNode = texture(map, mappedUv);
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-hero-showpiece';

  const group = new THREE.Group();
  group.add(mesh);
  group.position.set(0, -0.35, -0.6);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.billboard = (camera) => {
    if (!camera) return;
    mesh.quaternion.copy(camera.quaternion);
  };

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
